return $input.all().map((item, index) => {
  const row = item.json;
  return {
    json: {
      question_id: row.id,
      category: row.category,
      question: row.question,
      expected_sources: Array.isArray(row.expected_sources) ? row.expected_sources : [],
      expected_facts: Array.isArray(row.expected_facts) ? row.expected_facts : [],
      should_refuse: Boolean(row.should_refuse),
      evaluator_notes: row.evaluator_notes ?? '',
      evaluation_batch: Math.floor(index / 5) + 1
    }
  };
});

const row = $('Process One Question at a Time').item.json;

const chunks = $input.all().map((item, index) => {
  const document = item.json.document ?? {};
  const metadata = document.metadata ?? {};
  return {
    rank: index + 1,
    score: Number(item.json.score ?? 0),
    page_content: document.pageContent ?? '',
    document_id: metadata.document_id ?? '',
    title: metadata.title ?? '',
    source_file: metadata.source_file ?? '',
    source_url: metadata.source_url ?? ''
  };
});

const context = chunks.map(chunk =>
  `[Source ${chunk.rank}]\nTitle: ${chunk.title}\nFile: ${chunk.source_file}\nScore: ${chunk.score}\nContent: ${chunk.page_content}`
).join('\n\n---\n\n');

const sources = [...new Map(chunks.map(chunk => [chunk.source_file, {
  document_id: chunk.document_id,
  title: chunk.title,
  source_file: chunk.source_file,
  source_url: chunk.source_url
}])).values()].filter(source => source.source_file);

return [{
  json: {
    ...row,
    context,
    sources,
    chunks,
    retrieval_count: chunks.length,
    top_score: chunks[0]?.score ?? 0
  }
}];

const answer = String($json.text ?? $json.output ?? '');
const row = $('Build Evaluation Context').item.json;
const refusalText = `I couldn't find this in the provided enterprise architecture documents.`;

const normalize = value => String(value ?? '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

const answerNormalized = normalize(answer);
const stopWords = new Set(['about','after','again','against','because','before','being','between','could','does','from','have','into','must','only','other','should','than','that','their','there','these','they','this','those','through','under','using','when','where','which','with','would']);

const expectedFacts = row.expected_facts ?? [];
const factChecks = expectedFacts.map(fact => {
  const tokens = [...new Set(normalize(fact).split(' ').filter(token => token.length >= 4 && !stopWords.has(token)))];
  const matched = tokens.filter(token => answerNormalized.includes(token));
  const coverage = tokens.length ? matched.length / tokens.length : 1;
  return { fact, coverage, passed: coverage >= 0.65 };
});

const expectedSources = row.expected_sources ?? [];
const retrievedSources = (row.sources ?? []).map(source => source.source_file).filter(Boolean);
const citedSources = expectedSources.filter(source => answer.includes(source));
const sourceRecall = expectedSources.length
  ? citedSources.length / expectedSources.length
  : 1;
const factCoverage = factChecks.length
  ? factChecks.filter(check => check.passed).length / factChecks.length
  : 1;
const refused = answerNormalized.includes(normalize(refusalText));
const refusalCorrect = row.should_refuse ? refused : !refused;

let score;
if (row.should_refuse) {
  score = refusalCorrect ? 1 : 0;
} else {
  score = refusalCorrect ? (0.75 * factCoverage + 0.25 * sourceRecall) : 0;
}
score = Math.round(score * 100) / 100;

return [{
  json: {
    question_id: row.question_id,
    category: row.category,
    question: row.question,
    expected_sources: expectedSources,
    expected_facts: expectedFacts,
    should_refuse: row.should_refuse,
    evaluator_notes: row.evaluator_notes,
    evaluation_batch: row.evaluation_batch,
    actual_answer: answer,
    retrieved_sources: retrievedSources,
    cited_expected_sources: citedSources,
    top_score: row.top_score,
    retrieval_count: row.retrieval_count,
    fact_checks: factChecks,
    fact_coverage: factCoverage,
    source_recall: sourceRecall,
    refusal_correct: refusalCorrect,
    evaluation_score: score,
    passed: score >= 0.7
  }
}];

const results = $input.all().map(item => item.json);
const successful = results.filter(result => typeof result.evaluation_score === 'number');
const average = values => values.length
  ? Math.round((values.reduce((sum, value) => sum + value, 0) / values.length) * 100) / 100
  : 0;

const categories = {};
for (const result of successful) {
  categories[result.category] ??= [];
  categories[result.category].push(result.evaluation_score);
}

const categoryScores = Object.fromEntries(
  Object.entries(categories).map(([category, scores]) => [category, average(scores)])
);

return [{
  json: {
    run_status: successful.length === 15 ? 'complete' : 'incomplete',
    questions_expected: 15,
    questions_completed: successful.length,
    questions_passed: successful.filter(result => result.passed).length,
    overall_score: average(successful.map(result => result.evaluation_score)),
    average_fact_coverage: average(successful.map(result => result.fact_coverage)),
    average_source_recall: average(successful.map(result => result.source_recall)),
    refusal_accuracy: average(successful.filter(result => result.should_refuse).map(result => result.refusal_correct ? 1 : 0)),
    category_scores: categoryScores,
    failed_question_ids: successful.filter(result => !result.passed).map(result => result.question_id),
    results: successful
  }
}];
